Then, our VLB can be written as:
\begin{align}
  \log{p_{\theta}(G_{0})}  =&  \log{\left(\int p_{\theta}(G_{0:n})\frac{q_{\phi}(G_{1:n}|G_0)}{q_{\phi}(G_{1:n}|G_0)}dG_{1:n}\right)} \nonumber\\\\
                          \geq& E_{q_{\phi}(G_{1:n}|G_0)}\left( \log{p_{\theta}(G_{1:n})} + \log{p_{\theta}(G_0|G_{1:n})} - \log{q_{\phi}(G_{1:n}|G_{0})} \right) \nonumber\\\\
                          \overset{Eq.(r.3)}{=}&  E_{q_{\phi}(\sigma_{1:n}|G_0)}\left( \log{p_{\theta}(G_{1:n})} + \log{p_{\theta}(G_0|G_{1:n})} - \log{q_{\phi}(G_{1:n}|G_{0})} \right) \nonumber \\\\
                          \overset{Eq.(r.1)}{=}& E_{q_{\phi}(\sigma_{1:n}|G_0)}\left( \log{|\mathit{\Pi}(G_{1:n})|p_{\theta}(G_{1:n},\sigma_{1:n})} + \log{p_{\theta}(G_0|G_{1:n})} - \log{q_{\phi}(G_{1:n}|G_{0})} \right) \nonumber
                          \\\\
                                         \overset{Eq.(r.2)}{=}& E_{q_{\phi}(\sigma_{1:n}|G_0)}\left( \log{|\mathit{\Pi}(G_{1:n})|p_{\theta}(G_{1:n},\sigma_{1:n})} + \log{p_{\theta}(G_0|G_{1:n})} - \log{|\mathit{\Pi}(G_{1:n})|q_{\phi}(\sigma_{1:n}|G_{0})} \right) \nonumber
                          \\\\
                          =& E_{q_{\phi}(\sigma_{1:n}|G_0)}( \log{|\mathit{\Pi}(G_{1:n})|p_{\theta}(G_{1:n-1}|\sigma_{1:n})p(\sigma_{1:n}|G_n)p(G_n)} + \log{p_{\theta}(G_0|G_{1:n})}  \nonumber\\\\
                          & - \log{|\mathit{\Pi}(G_{1:n})|q_{\phi}(\sigma_{1:n}|G_{0})} ) \nonumber \\\\
                              =& E_{q_{\phi}(\sigma_{1:n}|G_0)} ( \log{p_{\theta}(G_{1:n-1}|\sigma_{1:n})} + \log{p_{\theta}(G_0|G_{1:n})} +\log{p(\sigma_{1:n}|G_n)} +\log{p(G_n)}\nonumber \\\\
                                                    & - \log{q_{
                              \phi}(\sigma_{1:n}|G_{0})}
                            + \log{|\mathit{\Pi}(G_{1:n})|}-\log{|\mathit{\Pi}(G_{1:n})|} ) \nonumber \\\\
 \overset{\log{p(G_n)=0}}{=}& E_{q_{\phi}(\sigma_{1:n}|G_0)} ( \log{p_{\theta}(G_{1:n-1}|\sigma_{1:n})} + \log{p_{\theta}(G_0|G_{1:n})} +\log{p(\sigma_{1:n}|G_n)} - \log{q_{
                              \phi}(\sigma_{1:n}|G_{0})} \nonumber \\\\\
                                                    =& E_{q_{\phi}(\sigma_{1:n}|G_0)}( \log{p_{\theta}(G_{0:n-1}|\sigma_{1:n}, G_n)} +\log{p(\sigma_{1:n}|G_n)} - \log{q_{\phi}(\sigma_{1:n}|G_{0})}
            )\nonumber \\\\
                                                               =& E_{q_{\phi}(\sigma_{1:n}|G_0)}\left( \log{p_{\theta}(G_{0:n-1}(\sigma_{1:n})|G_n)} +\log{p(\sigma_{1:n}|G_n)}- \log{q_{\phi}(\sigma_{1:n}|G_{0})}
                            \right)\nonumber \\\\
                                                        =& E_{q_{\phi}(\sigma_{1:n}|G_0)}\left( \log{p_{\theta}(G_{0:n-1}(\sigma_{1:n})|G_n)}+ \log{p(\sigma_{1:n}|G_n)}- \log{q_{\phi}(\sigma_{1:n}|G_{0})}
                            \right)\nonumber \\\\
                          =& E_{q_{\phi}(\sigma_{1:n}|G_0)}
                            \sum_{t=0}^{n-1}\log{p_{\theta}(G_t(\sigma_{1:n})|G_{t+1}(\sigma_{1:n}))}-\text{KL}(q_{\phi}(\sigma_{1:n}|G_0)|p(\sigma_{1:n}|G_n)).
\end{align}
We use $G_t(\sigma_{1:n})$ to denote the masked graph at time step $t$ under the node ordering $\sigma_{1:n}$. In the fifth last row, we have $\log p(G_n)=0$ because $G_n$ is a deterministic graph wherein all the nodes are masked. For brevity, we directly use $p_{\theta}(G_t|G_{t+1})$ to represent $p_{\theta}(G_t(\sigma_{1:n})|G_{t+1}(\sigma_{1:n}))$ in Eq. 3 since $\sigma_{1:n}$ already appears in the expectation over $q_{\phi}(\sigma_{1:n}|G_0)$.


We have also added this detailed derivation of the VLB in Appendix. A.3


In contrast, OM treats the node ordering as the latent variable and its VLB follows:

\begin{align}
\log p_{\theta}(G)=& \log \sum_{\sigma_{1:n}} p_{\theta}(G_{1:n},\sigma_{1:n}) \\\\
=& \log \sum_{\sigma_{1:n}} \frac{p_{\theta}(G_{1:n},\sigma_{1:n})q(\sigma_{1:n}|G)}{q(\sigma_{1:n}|G)} \\\\ \ge& E_{q(\sigma_{1:n}|G)}[\log p_{\theta}(G_{1:n},\sigma_{1:n})-\log q(\sigma_{1:n}|G)] \\\\
=&E_{q(\sigma_{1:n}|G_{0})}[\log \frac{1}{\Pi[G_{1:n}]}p_{\theta}(G_{1:n})-\log q(\sigma_{1:n}|G)]
\end{align}

As we can see, OM must compute $|\mathit{\Pi}(G_{1:n})|$ because it needs to model the joint probability $p(G,\sigma)$.
